WITH lines AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS tier_value), metrics AS (SELECT effective_from, tier_value, CUME_DIST() OVER (ORDER BY tier_value DESC) AS tier_value_cume_dist, CUME_DIST() OVER w_ordered AS tier_value_cume_dist_2, DENSE_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) AS tier_value_dense_rank FROM lines WINDOW w_ordered AS (ORDER BY tier_value NULLS FIRST)), scored AS (SELECT effective_from, tier_value_cume_dist_2, CUME_DIST() OVER (ORDER BY tier_value_cume_dist NULLS LAST) AS tier_value_cume_dist_cume_dist, CUME_DIST() OVER (ORDER BY tier_value_cume_dist DESC NULLS LAST) AS tier_value_cume_dist_cume_dist_2 FROM metrics), with_windows AS (SELECT effective_from, tier_value_cume_dist_2, CUME_DIST() OVER (ORDER BY tier_value_cume_dist_cume_dist DESC) AS tier_value_cume_dist_cume_dist_cume_dist, RANK() OVER (ORDER BY tier_value_cume_dist_cume_dist NULLS FIRST) AS tier_value_cume_dist_cume_dist_rank FROM scored WHERE tier_value_cume_dist_cume_dist_2 < 0.63) SELECT CASE WHEN tier_value_cume_dist_cume_dist_rank >= 7 THEN 'HIGH' ELSE 'LOW' END AS tier_value_cume_dist_cume_dist_rank_tier, COUNT(*) AS event_count, PERCENTILE_APPROX(tier_value_cume_dist_cume_dist_cume_dist, 0.9) AS tier_value_cume_dist_cume_dist_cume_dist_p90, SUM(tier_value_cume_dist_cume_dist_cume_dist) AS total_tier_value_cume_dist_cume_dist_cume_dist FROM with_windows GROUP BY tier_value_cume_dist_cume_dist_rank_tier ORDER BY tier_value_cume_dist_cume_dist_rank_tier DESC NULLS FIRST
